/** Every built-in template as a flat list, each carrying its category name. */
export const BUILTIN_TEMPLATES = Object.values(TEMPLATE_CATALOG).flatMap((category) =>
  Object.values(category.subcategories).flatMap((sub) =>
    sub.processes.map((proc) => ({ ...proc, category: category.name }))));

/**
 * Find a built-in template by file name ("nmc111_cell_manufacturing.json"),
 * template_id ("nmc111_cell_manufacturing") or catalog id ("nmc111").
 */
export function findBuiltinTemplate(key) {
  if (!key || typeof key !== 'string') return null;
  const k = key.toLowerCase();
  const stem = k.replace(/\.json$/, '');
  return BUILTIN_TEMPLATES.find((t) =>
    t.template === k || t.template.replace(/\.json$/, '') === stem || t.id === k) || null;
}

/** True when a saved template under `fileName` would shadow a built-in. */
export function isBuiltinTemplateFile(fileName) {
  if (!fileName) return false;
  const f = fileName.toLowerCase();
  return BUILTIN_TEMPLATES.some((t) => t.template === f);
}
